    async def search(
        self,
        *,
        cursor: typing.Optional[str] = OMIT,
        filter: typing.Optional[Filter] = OMIT,
        limit: typing.Optional[int] = OMIT,
        search_text: typing.Optional[str] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> AsyncPager[Account, SearchAccountsResponseBody]:
        """
        Optionally pass `search_text` for fuzzy matching. Results are intersected with any provided filter.

        Filterable fields and their allowed operators:

         Field | Allowed operators |
         --- | --- |
         `id` | `equals`, `in`, `not_in` |
         `domains` | `contains`, `does_not_contain`, `in`, `not_in` |
         `tags` | `contains`, `does_not_contain`, `in`, `not_in` |
         `name` | `equals`, `in`, `not_in`, `string_contains` |
         `external_ids` | `equals`, `in`, `not_in`, `is_set`, `is_unset` |
         `owner_id` | `equals`, `in`, `not_in`, `is_set`, `is_unset` |

        For custom fields, pass the field slug as `field`.

        **Rate limit:** 120 requests per minute

        Parameters
        ----------
        cursor : typing.Optional[str]
            The cursor to use for pagination.

        filter : typing.Optional[Filter]

        limit : typing.Optional[int]
            The number of accounts to fetch. Defaults to 100. Must be between 1 and 1000.

        search_text : typing.Optional[str]
            Fuzzy text search. Results are intersected with any provided filter.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        AsyncPager[Account, SearchAccountsResponseBody]


        Examples
        --------
        import asyncio

        from usepylon import AsyncPylon

        client = AsyncPylon(
            token="YOUR_TOKEN",
        )


        async def main() -> None:
            response = await client.accounts.search()
            async for item in response:
                yield item

            # alternatively, you can paginate page-by-page
            async for page in response.iter_pages():
                yield page


        asyncio.run(main())
        """
        return await self._raw_client.search(
            cursor=cursor, filter=filter, limit=limit, search_text=search_text, request_options=request_options
        )

